// `typeof o[k]` and `o[k](...)` are ONE question asked twice, and they
// answered differently.
//
// Object.prototype's methods and every primitive prototype's exist in
// this runtime as C branches inside scr_dyn_invoke.c, reachable from the
// CALL and from nowhere else. The READ walked own members and the STORED
// prototype chain -- which it really does walk -- missed, and answered
// the undefined singleton. So the same member on the same object was a
// function when called and `undefined` when read.
//
// 4153 found that with four rows. This package is the grid: every kind
// whose prototype the runtime models as a dispatch arm, both spellings,
// with the names the dispatch does NOT have as the control that says the
// read did not start claiming everything.
"use strict";

// Keys held in module-scope `var`s, the way protobufjs holds its own --
// a computed key the frontend cannot fold.
var KHOP = "hasOwnProperty", KVOF = "valueOf", KPUSH = "push", KJOIN = "join";
var KTRIM = "trim", KTS = "toString", KSPLIT = "split", KTOFIXED = "toFixed";
var KNOPE = "nope";

function dobj() { return JSON.parse('{"a":1}'); }
function darr() { return JSON.parse("[1,2,3]"); }
function dstr() { return JSON.parse('"  ab  "'); }
function dnum() { return JSON.parse("5"); }

// ---------------------------------------------------------------- OBJECT
// Object.prototype, the two names this runtime's dispatch answers.
exports.objHopElem = function () { var o = dobj(); return typeof o[KHOP]; };
exports.objHopDot = function () { var o = dobj(); return typeof o.hasOwnProperty; };
exports.objVofElem = function () { var o = dobj(); return typeof o[KVOF]; };
// The CALL beside them, which already worked -- the control that says
// the READ was the wrong one and not the call.
exports.objHopCall = function () { var o = dobj(); return String(o[KHOP]("a")); };
exports.objVofCall = function () { var o = dobj(); return String(o[KVOF]() === o); };

// THE OTHER CONTROL, and the one that matters most: names Object.prototype
// does NOT have still read `undefined`, exactly as Node does. A read that
// answered `function` for everything would pass every row above and be a
// worse bug than the one being fixed.
exports.objNope = function () { var o = dobj(); return typeof o[KNOPE]; };
exports.objPush = function () { var o = dobj(); return typeof o[KPUSH]; };
exports.objTrim = function () { var o = dobj(); return typeof o[KTRIM]; };

// An OWN member SHADOWS the prototype's. Both halves: the type and the
// value, so a read that answered the prototype over an own member would
// show up here rather than being invisible.
exports.shadowType = function () { var o = JSON.parse('{"hasOwnProperty":7}'); return typeof o[KHOP]; };
exports.shadowVal = function () { var o = JSON.parse('{"hasOwnProperty":7}'); return String(o[KHOP]); };
// And an own member whose VALUE is undefined is still an own member:
// Node reads `undefined`, not the prototype's function.
exports.ownUndef = function () { var o = dobj(); o.hasOwnProperty = undefined; return typeof o[KHOP]; };

// A null-prototype dictionary inherits NOTHING, Object.prototype
// included -- the row that says this is a real prototype question and not
// a name table. protobufjs's `_listeners` maps are exactly this shape.
exports.bareHop = function () { var o = Object.create(null); o.low = 1; return typeof o[KHOP]; };
exports.bareOwn = function () { var o = Object.create(null); o.low = 1; return typeof o[KNOPE]; };

// ---------------------------------------------------------------- ARRAY
exports.arrPush = function () { var a = darr(); return typeof a[KPUSH]; };
exports.arrJoin = function () { var a = darr(); return typeof a[KJOIN]; };
exports.arrHop = function () { var a = darr(); return typeof a[KHOP]; };
exports.arrNope = function () { var a = darr(); return typeof a[KNOPE]; };
exports.arrLen = function () { var a = darr(); return String(a["length"]); };
exports.arrPushCall = function () { var a = darr(); a[KPUSH](4); return String(a.join("-")); };

// ---------------------------------------------------------------- STRING
exports.strTrimElem = function () { var s = dstr(); return typeof s[KTRIM]; };
exports.strTrimDot = function () { var s = dstr(); return typeof s.trim; };
// A name String.prototype HAS and this runtime fences loudly rather than
// implementing (the regex family): Node says `function`, so the read says
// `function`, and the refusal arrives at the CALL where it belongs. A
// read of `undefined` here was a LIE about the member.
exports.strSplit = function () { var s = dstr(); return typeof s[KSPLIT]; };
exports.strNope = function () { var s = dstr(); return typeof s[KNOPE]; };
exports.strTrimCall = function () { var s = dstr(); return "[" + String(s[KTRIM]()) + "]"; };

// ---------------------------------------------------------------- NUMBER
exports.numTs = function () { var n = dnum(); return typeof n[KTS]; };
exports.numToFixed = function () { var n = dnum(); return typeof n[KTOFIXED]; };
exports.numNope = function () { var n = dnum(); return typeof n[KNOPE]; };
exports.numTsCall = function () { var n = dnum(); return String(n[KTS](2)); };

// A PROMISE receiver is deliberately NOT gridded here: `p[k]` on a
// promise-typed value never reaches the dyn read at all -- the frontend
// fences the element access while the receiver is still typed (SC1090,
// "element access on non-array values are not supported yet"). A `then`
// arm was written for the predicate and removed when this row proved it
// unreachable, rather than shipped as a control whose guarded region
// never runs.

// ------------------------------------------------------------ TRUTHINESS
// The shape the bug actually broke: a feature-detecting branch. Both
// directions, so a read stuck on either answer fails one of them.
exports.detect = function () { var o = dobj(); return o[KHOP] ? "has" : "missing"; };
exports.detectNope = function () { var o = dobj(); return o[KNOPE] ? "has" : "missing"; };

// ------------------------------------------------- THE OWN-ONLY SURFACES
// Object.keys, `in`, JSON and the own-property questions ask something
// different and must keep answering it. If the read's new answer had
// leaked into the member TABLE, these are where it would show.
exports.keys = function () { var o = dobj(); return Object.keys(o).join(","); };
exports.inOwn = function () { var o = dobj(); return String("a" in o); };
exports.inProto = function () { var o = dobj(); return String("hasOwnProperty" in o); };
exports.inProtoVar = function () { var o = dobj(); return String(KHOP in o); };
exports.inProtoArr = function () { var a = darr(); return String("push" in a); };
exports.hasOwnStatic = function () { var o = dobj(); return String(Object.hasOwn(o, KHOP)); };
exports.json = function () { var o = dobj(); return JSON.stringify(o); };
exports.spread = function () { var o = dobj(); return JSON.stringify(Object.assign({}, o)); };
